import math
def objs8(grid,bg):
    Hh,Ww=len(grid),len(grid[0]); seen=set(); res=[]
    for r in range(Hh):
        for c in range(Ww):
            if grid[r][c]!=bg and (r,c) not in seen:
                col=grid[r][c]; st=[(r,c)]; cells=[]
                seen.add((r,c))
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<Hh and 0<=y<Ww and (x,y) not in seen and grid[x][y]==col:
                                seen.add((x,y)); st.append((x,y))
                res.append((col,sorted(cells)))
    return res
def sym(cells):
    for _ in range(2):
        for _ in range(4):
            yield norm(cells)
            cells=[(c,-r) for r,c in cells]
        cells=[(-r,c) for r,c in cells]
def shapekey(cells):
    return min(sym(cells))
def dups(objs):
    d=defaultdict(list)
    for col,o in objs: d[shapekey(o)].append((col,o))
    return {s:v for s,v in d.items() if len(v)>1}
def center(cells): 
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    return (sum(rs)/len(rs), sum(cs)/len(cs))
def dist(a,b): return math.dist(a,b)

